import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Nguyên tắc Cơ bản của Lùi lại Thời gian","description":"","frontmatter":{},"headers":[],"relativePath":"vi/82-时间回溯基本原则.md","filePath":"vi/82-时间回溯基本原则.md"}'),a={name:"vi/82-时间回溯基本原则.md"};function g(l,n,u,o,r,p){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="nguyen-tac-co-ban-cua-lui-lai-thoi-gian" tabindex="-1">Nguyên tắc Cơ bản của Lùi lại Thời gian <a class="header-anchor" href="#nguyen-tac-co-ban-cua-lui-lai-thoi-gian" aria-label="Permalink to &quot;Nguyên tắc Cơ bản của Lùi lại Thời gian&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>82</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Lùi lại thời gian, quan sát trước sau đó can thiệp hạn chế, ổn định dòng thời gian, bảo toàn nhân quả, neo neo</td></tr></tbody></table><h2 id="_1-đinh-nghia-va-ban-chat-cua-lui-lai-thoi-gian" tabindex="-1">1. Định nghĩa và Bản chất của Lùi lại Thời gian <a class="header-anchor" href="#_1-đinh-nghia-va-ban-chat-cua-lui-lai-thoi-gian" aria-label="Permalink to &quot;1. Định nghĩa và Bản chất của Lùi lại Thời gian&quot;">​</a></h2><p>Lùi lại thời gian đề cập đến hành động gửi ý thức, thông tin hoặc vật chất trở lại nút thời gian trong quá khứ thông qua khả năng vận hành chiều thời gian của mạng lưới luật pháp neo. Trong khuôn khổ luật pháp của Hengyuanzhou, thời gian không phải là dòng chảy tuyến tính một chiều không thể đảo ngược, mà là một chiều có thể vận hành trong mạng lưới luật pháp. Tuy nhiên, vận hành chiều thời gian có rủi ro cực kỳ cao và các hạn chế nghiêm ngặt; bất kỳ hành động lùi lại thời gian nào cũng có thể gây ra xáo trộn chuỗi nhân quả, phân chia dòng thời gian, thậm chí là dao động luật pháp cấp độ vũ trụ.</p><p>Bản chất của lùi lại thời gian là &quot;tạo ra một kênh lùi lại trên chiều thời gian của mạng lưới luật pháp, cho phép thông tin hoặc năng lượng cụ thể lan truyền ngược theo kênh&quot;. Quá trình này đòi hỏi tiêu thụ một lượng lớn năng lượng neo, và thời gian lùi lại càng xa, nội dung lùi lại càng phức tạp, mức tiêu thụ năng lượng tăng theo cấp số nhân. Hiện tại, khả năng công nghệ của Hengyuanzhou chỉ hỗ trợ lùi lại ở cấp độ ý thức và thông tin; lùi lại hoàn chỉnh ở cấp độ vật chất vẫn đang trong giai đoạn nghiên cứu lý thuyết.</p><p>Cần nhấn mạnh đặc biệt rằng lùi lại thời gian không tương đương với &quot;du hành thời gian&quot;. Người lùi lại không đi vào quá khứ dưới dạng vật chất hoàn chỉnh, mà đến nút thời gian mục tiêu dưới dạng hình chiếu ý thức hoặc gói thông tin. Sự tồn tại của người lùi lại trong giai đoạn quá khứ là &quot;bán trong suốt&quot; — có thể quan sát, nhưng khả năng tương tác vật chất bị hạn chế nghiêm ngặt. Bản thân thiết kế này là một phần của cơ chế an toàn lùi lại thời gian.</p><h2 id="_2-bay-nguyen-tac-co-ban-cua-lui-lai-thoi-gian" tabindex="-1">2. Bảy Nguyên tắc Cơ bản của Lùi lại Thời gian <a class="header-anchor" href="#_2-bay-nguyen-tac-co-ban-cua-lui-lai-thoi-gian" aria-label="Permalink to &quot;2. Bảy Nguyên tắc Cơ bản của Lùi lại Thời gian&quot;">​</a></h2><p>Vận hành lùi lại thời gian của Hengyuanzhou tuân theo bảy nguyên tắc cơ bản sau, được Hội đồng Neo thiết lập dưới dạng nghị quyết đặc biệt, có hiệu lực pháp lý chỉ đứng sau hiến pháp:</p><table tabindex="0"><thead><tr><th>Số nguyên tắc</th><th>Tên nguyên tắc</th><th>Nội dung cốt lõi</th></tr></thead><tbody><tr><td>Nguyên tắc thứ nhất</td><td>Quan sát trước, sau đó can thiệp hạn chế</td><td>Bất kỳ việc lùi lại nào cũng phải hoàn thành giai đoạn quan sát thuần túy trước, và chỉ sau khi xác nhận không có rủi ro đáng kể mới có thể thực hiện can thiệp hạn chế</td></tr><tr><td>Nguyên tắc thứ hai</td><td>Bảo toàn nhân quả</td><td>Hành động lùi lại không được thay đổi chuỗi nhân quả cốt lõi đã xảy ra; độ lệch nhân quả phát sinh từ việc lùi lại phải được sửa chữa sau khi lùi lại kết thúc</td></tr><tr><td>Nguyên tắc thứ ba</td><td>Neo neo</td><td>Tất cả các vận hành lùi lại phải có neo ổn định làm gốc tọa độ thời gian; việc lùi lại mù mà không có neo bị cấm</td></tr><tr><td>Nguyên tắc thứ tư</td><td>Tác động tối thiểu</td><td>Tất cả các hành động trong quá trình lùi lại phải tuân theo nguyên tắc tác động tối thiểu, giảm thiểu xáo trộn đối với dòng thời gian quá khứ</td></tr><tr><td>Nguyên tắc thứ năm</td><td>Có thể truy vết</td><td>Mỗi lần lùi lại phải ghi nhật ký vận hành đầy đủ, bao gồm danh tính người lùi lại, thời gian mục tiêu, nội dung quan sát, hành động can thiệp và đánh giá độ lệch nhân quả</td></tr><tr><td>Nguyên tắc thứ sáu</td><td>Cấm nghịch lý</td><td>Bất kỳ vận hành nào có thể gây ra nghịch lý thời gian đều bị nghiêm cấm, bao gồm nhưng không giới hạn ở nghịch lý ông nội, nghịch lý thông tin và nghịch lý bản thể học</td></tr><tr><td>Nguyên tắc thứ bảy</td><td>Kiểm toán sau</td><td>Sau khi lùi lại kết thúc, phải thực hiện kiểm toán sau bởi ủy ban kiểm toán luật pháp thời gian độc lập, để xác nhận rằng không có xáo trộn dòng thời gian không thể kiểm soát</td></tr></tbody></table><p>Trong bảy nguyên tắc, &quot;quan sát trước, sau đó can thiệp hạn chế&quot; là nguyên tắc vận hành cốt lõi nhất, và sáu nguyên tắc còn lại đều xoay quanh cốt lõi này. Các quy phạm vận hành chi tiết của nguyên tắc này có thể xem tại Tài liệu 83 &quot;Hướng dẫn Quan sát Trước, Sau đó Can thiệp Hạn chế&quot;.</p><h2 id="_3-quan-ly-phan-loai-lui-lai-thoi-gian" tabindex="-1">3. Quản lý Phân loại Lùi lại Thời gian <a class="header-anchor" href="#_3-quan-ly-phan-loai-lui-lai-thoi-gian" aria-label="Permalink to &quot;3. Quản lý Phân loại Lùi lại Thời gian&quot;">​</a></h2><p>Theo khoảng thời gian và mức độ can thiệp của việc lùi lại, vận hành lùi lại thời gian được chia thành ba cấp độ quản lý:</p><ol><li><p><strong>Lùi lại Cấp 1 (Quan sát Thời gian Gần)</strong>: Khoảng thời gian lùi lại không vượt quá 100 năm thời gian tiêu chuẩn của mặt phẳng自己, và chỉ thực hiện quan sát thuần túy mà không có bất kỳ can thiệp nào. Được Cục Quản lý Mặt phẳng phê duyệt; quá trình vận hành phải có hai hoặc nhiều giám sát viên luật pháp thời gian có mặt để giám sát.</p></li><li><p><strong>Lùi lại Cấp 2 (Quan sát Thời gian Xa)</strong>: Khoảng thời gian lùi lại vượt quá 100 năm nhưng không vượt quá 10.000 năm, hoặc quá trình lùi lại cần can thiệp cực kỳ nhẹ (như truyền một thông tin). Phải được Ủy ban Luật pháp Thời gian thuộc Hội đồng Neo phê duyệt, và phải lập kế hoạch khẩn cấp về độ lệch nhân quả chi tiết.</p></li><li><p><strong>Lùi lại Cấp 3 (Can thiệp Sâu)</strong>: Khoảng thời gian lùi lại vượt quá 10.000 năm, hoặc quá trình lùi lại cần can thiệp thực chất. Phải được đa số trên hai phần ba trong cuộc họp toàn thể của Hội đồng Neo thông qua, và được Tòa án Cộng sinh xem xét về việc vi hiến, để xác nhận rằng hành động can thiệp phù hợp với các nguyên tắc cơ bản của Hiến pháp Cộng sinh.</p></li></ol><p>Bất kỳ cấp độ lùi lại thời gian nào cũng bị cấm cho các mục đích sau: tìm lợi ích tư nhân cho cá nhân hoặc nhóm nhỏ, thay đổi số phận của nhân vật lịch sử để thỏa mãn mong muốn cá nhân, làm sai lệch quá trình tự nhiên của tiến hóa văn minh, và bất kỳ hình thức vận hành &quot;chủ nghĩa sửa đổi lịch sử&quot; nào.</p><h2 id="_4-han-che-nang-luong-va-cong-nghe-cua-lui-lai-thoi-gian" tabindex="-1">4. Hạn chế Năng lượng và Công nghệ của Lùi lại Thời gian <a class="header-anchor" href="#_4-han-che-nang-luong-va-cong-nghe-cua-lui-lai-thoi-gian" aria-label="Permalink to &quot;4. Hạn chế Năng lượng và Công nghệ của Lùi lại Thời gian&quot;">​</a></h2><p>Mức tiêu thụ năng lượng của lùi lại thời gian là cực kỳ lớn. Lấy lùi lại hình chiếu ý thức làm ví dụ, năng lượng cần thiết để lùi lại 1 năm là khoảng 10.000 đơn vị năng lượng tiêu chuẩn, để lùi lại 100 năm là khoảng 1 triệu đơn vị năng lượng tiêu chuẩn, và để lùi lại 10.000 năm cần khoảng 10 tỷ đơn vị năng lượng tiêu chuẩn. Mức tiêu thụ năng lượng và khoảng thời gian lùi lại có mối quan hệ gần như logarit-tuyến tính, nhưng khi vượt qua các nút lịch sử quan trọng sẽ xuất hiện đỉnh năng lượng — điều này là do mật độ chuỗi nhân quả tại các nút lịch sử quan trọng là cực kỳ cao, và vận hành lùi lại cần vượt qua quán tính nhân quả lớn hơn.</p><p>Về mặt công nghệ, lùi lại thời gian đòi hỏi sự phối hợp làm việc giữa &quot;thiết bị neo luật pháp thời gian&quot; và &quot;dãy truyền hình chiếu ý thức&quot;. Thiết bị thứ nhất chịu trách nhiệm thiết lập tọa độ thời gian ổn định tại nút thời gian mục tiêu, thiết bị thứ hai chịu trách nhiệm gửi hình chiếu ý thức của người lùi lại một cách an toàn và duy trì sự tồn tại của nó trong giai đoạn quá khứ. Tất cả các thiết bị lùi lại phải trải qua chứng nhận an toàn của Ủy ban Giám sát Neo; việc sử dụng thiết bị tự chế chưa được chứng nhận để vận hành lùi lại bị cấm.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Lùi lại thời gian là một trong những khả năng vận hành luật pháp mạnh mẽ và nguy hiểm nhất của Hengyuanzhou. Bảy nguyên tắc cơ bản và hệ thống quản lý phân loại cùng nhau cấu thành khuôn khổ an toàn của lùi lại thời gian, tinh thần cốt lõi của nó là &quot;kính trọng nhân quả, vận hành một cách thận trọng&quot;. Mục đích hợp pháp của lùi lại thời gian chỉ giới hạn trong nghiên cứu khảo cổ, khôi phục sự thật lịch sử và cảnh báo sớm về khủng hoảng cấp độ tuyệt chủng; bất kỳ việc sử dụng nào vượt quá phạm vi này sẽ bị coi là sự phạm thượng đối với luật pháp vũ trụ.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>83-Hướng dẫn Quan sát Trước, Sau đó Can thiệp Hạn chế</li><li>84-Cơ chế Phòng ngừa và Kiểm soát Nghịch lý Thời gian</li><li>85-Tổng cương Nghị định thư Khảo cổ</li></ul>',21)])])}const m=h(a,[["render",g]]);export{e as __pageData,m as default};
